"use strict";(self.webpackChunkcoinray_strategy_docs=self.webpackChunkcoinray_strategy_docs||[]).push([["2059"],{8877(e,t,n){n.r(t),n.d(t,{metadata:()=>r,default:()=>h,frontMatter:()=>i,contentTitle:()=>l,toc:()=>d,assets:()=>c});var r=JSON.parse('{"id":"examples","title":"Examples","description":"Three complete scripts. Each one is compiled and run by the SDK\'s test suite,","source":"@site/docs/examples.mdx","sourceDirName":".","slug":"/examples","permalink":"/strategy-docs/examples","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":10,"frontMatter":{"sidebar_position":10,"title":"Examples"},"sidebar":"guides","previous":{"title":"Exchange data","permalink":"/strategy-docs/exchange-data"},"next":{"title":"Porting from Pine Script","permalink":"/strategy-docs/porting-from-pine"}}'),a=n(4848),o=n(8453),s=n(1113);let i={sidebar_position:10,title:"Examples"},l="Examples",c={},d=[{value:"HTF trend pullback",id:"htf-trend-pullback",level:2},{value:"CVD divergence",id:"cvd-divergence",level:2},{value:"Weekly VWAP band reversion",id:"weekly-vwap-band-reversion",level:2}];function p(e){let t={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"examples",children:"Examples"})}),"\n",(0,a.jsx)(t.p,{children:"Three complete scripts. Each one is compiled and run by the SDK's test suite,\nso the code on this page always works with the current SDK."}),"\n",(0,a.jsx)(t.h2,{id:"htf-trend-pullback",children:"HTF trend pullback"}),"\n",(0,a.jsx)(t.p,{children:"A strategy that buys RSI pullbacks on the chart timeframe while a\nhigher-timeframe EMA points up. It sizes each trade by risk and trails the stop\nonce the trade is 1R in profit."}),"\n",(0,a.jsxs)(t.p,{children:["Uses: ",(0,a.jsx)(t.a,{href:"/strategy-docs/multi-timeframe",children:"multi-timeframe"}),", input groups and tooltips,\n",(0,a.jsx)(t.a,{href:"/strategy-docs/orders-and-backtesting",children:"risk-based sizing and a trailing stop"}),", account\nread-back, ",(0,a.jsx)(t.a,{href:"/strategy-docs/alerts",children:"alert placeholders"}),"."]}),"\n",(0,a.jsx)(s.A,{language:"ts",title:"htf_trend_pullback.ts",children:'// HTF trend pullback (strategy).\n//\n// Trades pullbacks on the chart timeframe in the direction of a higher-timeframe\n// EMA. Shows: request.timeframe + param.timeframe, an indicator running on the\n// higher timeframe, risk-based sizing, a trailing stop, account read-back and\n// alert placeholders.\nimport { src, ta, param, config, request, strategy, Side, plot, plotPane, declarePlot, hline, PlotStyle, Stroke, color, alert, declareAlert, isNewBar, math } from "@coinray/strategy";\nconst tf = param.timeframe("Trend timeframe", "240");\nparam.meta("Trend timeframe", "Trend", "Must be a multiple of the chart timeframe, up to 1 day");\nconst trendLen = param.int("Trend EMA", 50, 5, 400);\nparam.meta("Trend EMA", "Trend");\nconst rsiLen = param.int("RSI length", 14, 2, 100);\nconst rsiBuy = param.float("RSI pullback level", 35.0, 5.0, 50.0);\nconst riskPct = param.float("Risk per trade %", 1.0, 0.1, 10.0);\nparam.meta("Risk per trade %", "Risk", "Position size so that the stop costs this share of equity");\nconst atrMult = param.float("Stop ATR multiple", 2.0, 0.5, 10.0);\nparam.meta("Stop ATR multiple", "Risk");\nconst trailPct = param.float("Trailing stop %", 1.5, 0.1, 20.0);\nparam.meta("Trailing stop %", "Risk");\n// Top level only. 60 higher-timeframe bars is enough to warm the default EMA.\nconst htf = request.timeframe(tf, trendLen + 10);\nconfig.warmup(50);\ndeclarePlot("trend", color.orange, 2);\ndeclarePlot("rsi", color.purple, 1, PlotStyle.Line, "rsi");\nhline(rsiBuy, color.green, Stroke.Dashed, "rsi");\ndeclareAlert("pullback_long");\nexport function onBar() {\n    // Runs on the higher timeframe because its input is an HTF series.\n    const trend = ta.ema(htf.close, trendLen);\n    const rsi = ta.rsi(src.close, rsiLen);\n    const atr = ta.atr(14); // no source argument: always the chart timeframe\n    plot("trend", trend[1]); // [1] = last CLOSED higher-timeframe bar, never repaints\n    plotPane("rsi", rsi, "rsi");\n    if (!isNewBar()) return;\n    const close = src.close[0];\n    const uptrend = htf.close[1] > trend[1] && trend[1] > trend[2];\n    const pullback = rsi[1] < rsiBuy && rsi[0] >= rsiBuy; // RSI crosses back up\n    if (!uptrend || !pullback || strategy.positionSize() != 0) return;\n    const stop = math.roundToMintick(close - atrMult * atr[0]);\n    // Start trailing only once the trade is 1R in profit.\n    const activation = math.roundToMintick(close + (close - stop));\n    strategy.order("pullback", Side.Long).marketEntry().stopLoss(stop).trailingStop(trailPct, activation).qtyRiskBased(riskPct).submit();\n    plot("stop", stop);\n    alert("pullback_long", \'{{ticker}} {{interval}}: long at {{close}}, stop {{plot("stop")}}, trend {{plot("trend")}}\');\n}\n'}),"\n",(0,a.jsx)(t.h2,{id:"cvd-divergence",children:"CVD divergence"}),"\n",(0,a.jsx)(t.p,{children:"An indicator that flags new highs and lows which order flow does not confirm,\nusing the correlation between price and cumulative volume delta."}),"\n",(0,a.jsxs)(t.p,{children:["Uses: ",(0,a.jsx)(t.a,{href:"/strategy-docs/exchange-data",children:"order flow"}),", ",(0,a.jsx)(t.code,{children:"ta.correlation"}),", declared plot styles\nand levels, ",(0,a.jsx)(t.a,{href:"/strategy-docs/drawing",children:"labels with callout styles"}),"."]}),"\n",(0,a.jsx)(s.A,{language:"ts",title:"cvd_divergence.ts",children:'// CVD divergence (indicator).\n//\n// Compares price with cumulative volume delta (aggressive buys minus sells).\n// When price and CVD stop moving together, the move is not backed by order\n// flow. Shows: orderflow(), ta.correlation, declared plot styles, hline, the\n// label builder with Pine callout styles, and nz() for markets without data.\n//\n// Order flow is `na` on exchanges without coverage and in the browser preview;\n// the script then simply plots nothing.\nimport { src, ta, param, config, orderflow, plotPane, declarePlot, hline, PlotStyle, Stroke, color, draw, LabelStyle, Size, YLoc, alert, declareAlert, isNewBar, barTime, na } from "@coinray/strategy";\nconst len = param.int("Correlation length", 30, 5, 200);\nconst level = param.float("Divergence below", -0.3, -1.0, 0.5);\nparam.meta("Divergence below", "", "Price/CVD correlation under this value counts as a divergence");\nconst lookback = param.int("Swing lookback", 20, 5, 200);\nconst flow = orderflow(); // top level only\nconfig.warmup(60);\ndeclarePlot("delta", color.withTransp(color.blue, 40), 1, PlotStyle.Columns, "flow");\ndeclarePlot("cvd", color.teal, 2, PlotStyle.Line, "cvd");\ndeclarePlot("corr", color.orange, 1, PlotStyle.Line, "corr");\nhline(0.0, color.gray, Stroke.Dotted, "corr");\nhline(level, color.red, Stroke.Dashed, "corr");\ndeclareAlert("cvd_bearish_divergence");\ndeclareAlert("cvd_bullish_divergence");\nexport function onBar() {\n    const cvd = flow.cvd; // read delta / cvd inside onBar\n    const corr = ta.correlation(src.close, cvd, len);\n    plotPane("delta", flow.delta, "flow");\n    plotPane("cvd", cvd, "cvd");\n    plotPane("corr", corr, "corr");\n    // [1]: the newest live bar\'s order flow is provisional.\n    if (!isNewBar() || na(corr[1]) || corr[1] >= level) return;\n    const newHigh = src.high[1] >= ta.highest(src.high, lookback)[1];\n    const newLow = src.low[1] <= ta.lowest(src.low, lookback)[1];\n    const t = barTime();\n    if (newHigh && cvd[1] < ta.highest(cvd, lookback)[1]) {\n        draw.labelEx(t, src.high[0], "CVD div").textColor(color.white).bg(color.red).size(Size.Small).style(LabelStyle.LabelDown).yloc(YLoc.AboveBar).draw("div_" + t.toString());\n        alert("cvd_bearish_divergence", "{{ticker}} {{interval}}: new high at {{high}} without CVD confirmation");\n    } else if (newLow && cvd[1] > ta.lowest(cvd, lookback)[1]) {\n        draw.labelEx(t, src.low[0], "CVD div").textColor(color.white).bg(color.green).size(Size.Small).style(LabelStyle.LabelUp).yloc(YLoc.BelowBar).draw("div_" + t.toString());\n        alert("cvd_bullish_divergence", "{{ticker}} {{interval}}: new low at {{low}} without CVD confirmation");\n    }\n}\n'}),"\n",(0,a.jsx)(t.h2,{id:"weekly-vwap-band-reversion",children:"Weekly VWAP band reversion"}),"\n",(0,a.jsx)(t.p,{children:"A strategy that fades closes back inside the weekly VWAP bands, targets the\nVWAP and the opposite band, and skips longs while funding is expensive."}),"\n",(0,a.jsxs)(t.p,{children:["Uses: ",(0,a.jsx)(t.code,{children:"ta.vwapBands"}),", ",(0,a.jsx)(t.a,{href:"/strategy-docs/exchange-data",children:"funding rate"})," with a filter that is\nsafe on spot, a plot fill, ",(0,a.jsx)(t.a,{href:"/strategy-docs/drawing",children:"boxes and lines"})," with ",(0,a.jsx)(t.code,{children:"extend"})," and\ntext, ",(0,a.jsx)(t.code,{children:"barstate"})," and ",(0,a.jsx)(t.code,{children:"syminfo"}),"."]}),"\n",(0,a.jsx)(s.A,{language:"ts",title:"vwap_band_reversion.ts",children:'// Weekly VWAP band reversion (strategy).\n//\n// Fades stretches beyond the weekly anchored VWAP bands back to the VWAP, and\n// skips longs while funding is expensive. Shows: ta.vwapBands with an anchor,\n// derivatives() with a na-safe filter, the box and line builders with extend\n// and text, plot fills, barstate and syminfo.\nimport { src, ta, param, config, derivatives, strategy, Side, plot, declarePlot, color, draw, Extend, Size, Align, Stroke, Anchor, isNewBar, barTime, barstate, syminfo, nz, log } from "@coinray/strategy";\nconst mult = param.float("Band stdev", 2.0, 0.5, 5.0);\nconst maxFunding = param.float("Max funding % (longs)", 0.03, 0.0, 1.0);\nparam.meta("Max funding % (longs)", "Filters", "Per funding interval. Ignored on spot and on exchanges without funding data");\nconst slPct = param.float("Stop beyond band %", 1.0, 0.1, 10.0);\nconst deriv = derivatives(); // top level only\nconfig.warmup(200);\nconst band = color.withTransp(color.blue, 85);\ndeclarePlot("vwap", color.blue, 2);\ndeclarePlot("upper", color.withTransp(color.blue, 40), 1, 0, "", "lower", band); // fill upper..lower\ndeclarePlot("lower", color.withTransp(color.blue, 40));\nexport function onBar() {\n    const vb = ta.vwapBands(src.hlc3, Anchor.Week, mult);\n    plot("vwap", vb.vwap);\n    plot("upper", vb.upper);\n    plot("lower", vb.lower);\n    if (barstate.isFirst()) log.info("running on " + syminfo.ticker() + " (" + syminfo.type() + ")");\n    if (!isNewBar()) return;\n    const close = src.close[0];\n    const t = barTime();\n    // nz(): funding is na on spot, so the filter passes there instead of blocking.\n    const fundingPct = nz(deriv.fundingRate[0]) * 100.0;\n    const flat = strategy.positionSize() == 0;\n    // Re-entry into the bands after a close outside them.\n    const longSetup = src.close[1] < vb.lower[1] && close > vb.lower[0];\n    const shortSetup = src.close[1] > vb.upper[1] && close < vb.upper[0];\n    if (flat && longSetup && fundingPct <= maxFunding) {\n        const stop = src.low[1] * (1.0 - slPct / 100.0);\n        strategy.order("fade_long", Side.Long).marketEntry().takeProfit(vb.vwap[0], 0.5).takeProfit(vb.upper[0], 0.5).stopLoss(stop).qtyPercentEquity(25).submit();\n        zone("long", t, stop, vb.vwap[0], color.green);\n    } else if (flat && shortSetup) {\n        const stop = src.high[1] * (1.0 + slPct / 100.0);\n        strategy.order("fade_short", Side.Short).marketEntry().takeProfit(vb.vwap[0], 0.5).takeProfit(vb.lower[0], 0.5).stopLoss(stop).qtyPercentEquity(25).submit();\n        zone("short", t, stop, vb.vwap[0], color.red);\n    }\n}\n// One trade zone per direction: re-drawing the same id moves it.\nfunction zone(side, t, stop, target, c) {\n    draw.boxEx(t, stop, t + 3600, target).fill(color.withTransp(c, 88)).border(c, 1, Stroke.Dotted).extend(Extend.Right).text(side + " to VWAP", c, Size.Small, Align.Left, Align.Top).draw("zone_" + side);\n    draw.lineEx(t, stop, t + 3600, stop).color(c).style(Stroke.Dashed).extend(Extend.Right).label("stop", 1.0, c, Size.Tiny).draw("stop_" + side);\n}\n'})]})}function h(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(p,{...e})}):p(e)}}}]);